{
  "findings": [
    {
      "check_id": "CKV2_AZURE_33",
      "title": "Storage account lacks a private endpoint",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account has no associated private endpoint, so storage traffic cannot be routed privately through an Azure virtual network."
    },
    {
      "check_id": "CKV2_AZURE_38",
      "title": "Storage soft delete is not enabled",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "No blob or container retention policies are configured, leaving deleted storage data without a recovery window."
    },
    {
      "check_id": "CKV2_AZURE_47",
      "title": "Blob anonymous access is not disabled",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The account does not explicitly disable public access for nested storage items, allowing containers to potentially be configured for anonymous access."
    },
    {
      "check_id": "CKV_AZURE_36",
      "title": "Trusted Microsoft Services bypass is not enabled",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account has no network rules permitting trusted Azure services to bypass its network restrictions."
    },
    {
      "check_id": "CKV2_AZURE_41",
      "title": "SAS expiration policy is not configured",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The account does not define a SAS expiration policy, allowing shared access signatures to be issued without an enforced expiration interval."
    }
  ],
  "patched_code": "variable "notification_storage_private_endpoint_subnet_id" {
  description = "Resource ID of the subnet used by the notification storage private endpoint."
  type        = string
}

resource "azurerm_storage_account" "notification_storage" {
  name                         = "smartgridscada${random_string.suffix.result}"
  resource_group_name          = azurerm_resource_group.smart_grid_rg.name
  location                     = azurerm_resource_group.smart_grid_rg.location
  account_tier                 = "Standard"
  account_replication_type     = "LRS"
  enable_https_traffic_only    = false
  allow_nested_items_to_be_public = false

  network_rules {
    default_action = "Deny"
    bypass         = ["AzureServices"]
  }

  blob_properties {
    delete_retention_policy {
      days = 7
    }

    container_delete_retention_policy {
      days = 7
    }
  }

  sas_policy {
    expiration_period = "01.00:00:00"
    expiration_action = "Log"
  }
}

resource "azurerm_private_endpoint" "notification_storage" {
  name                = "${azurerm_storage_account.notification_storage.name}-blob-pe"
  location            = azurerm_resource_group.smart_grid_rg.location
  resource_group_name = azurerm_resource_group.smart_grid_rg.name
  subnet_id           = var.notification_storage_private_endpoint_subnet_id

  private_service_connection {
    name                           = "${azurerm_storage_account.notification_storage.name}-blob-connection"
    private_connection_resource_id = azurerm_storage_account.notification_storage.id
    subresource_names              = ["blob"]
    is_manual_connection           = false
  }
}
",
  "fix_summary": "Disabled anonymous blob access, enabled blob and container soft-delete retention, added a SAS expiration policy, and restricted network access while permitting trusted Azure services. Added a blob private endpoint using a required subnet ID variable."
}
